@app.post("/image/generate")
async def generate_image_api(request: Request):
    """
    Body JSON:
    {
      "prompt": "élénk rózsaszínű futurisztikus városi tájkép neonfényekkel",
      "size": "1024x1024",
      "style": "photorealistic | illustration | anime | minimal",
      "seed": 12345
    }
    """
    if not GOOGLE_API_KEY:
        raise HTTPException(status_code=400, detail="Hiányzik a GOOGLE_API_KEY környezeti változó.")

    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Érvénytelen JSON.")

    prompt = (payload.get("prompt") or "").strip()
    if not prompt:
        raise HTTPException(status_code=400, detail="Üres prompt.")

    size = (payload.get("size") or "1024x1024").lower()
    if "x" not in size:
        size = "1024x1024"
    width, height = 1024, 1024
    try:
        w, h = size.split("x")
        width = max(256, min(2048, int(w)))
        height = max(256, min(2048, int(h)))
    except Exception:
        pass

    style = (payload.get("style") or "").strip()
    seed = payload.get("seed")

    # Google Generative Language Images API hívás (Imagen 4 Ultra)
    # Lásd: https://ai.google.dev/ (Images API), a pontos mezők régiótól/kiadástól függhetnek.
    body = {
        "model": "imagen-4.0-ultra",
        "prompt": {
            "text": prompt
        },
        "image": {
            "width": width,
            "height": height
        }
    }
    # Opcionális paraméterek, ha támogatottak
    if style:
        body["style"] = style
    if isinstance(seed, int):
        body["seed"] = seed

    try:
        resp = requests.post(
            IMAGEN_ENDPOINT,
            params={"key": GOOGLE_API_KEY},
            headers={"Content-Type": "application/json"},
            json=body,
            timeout=120
        )
        if resp.status_code != 200:
            raise HTTPException(status_code=resp.status_code, detail=f"Google API hiba: {resp.text}")

        data = resp.json()
        # A válasz szerkezete a kiadástól függ; a legtöbbször egy vagy több kép base64-ben jön.
        # Példa: {"images":[{"mimeType":"image/png","data":"<base64>"}]}
        images = []
        if isinstance(data, dict) and "images" in data and isinstance(data["images"], list):
            for im in data["images"]:
                b64 = im.get("data")
                mime = im.get("mimeType", "image/png")
                if b64:
                    images.append({"b64": b64, "mime": mime})
        else:
            raise HTTPException(status_code=500, detail="Váratlan Google API válaszformátum.")

        return JSONResponse({"images": images, "width": width, "height": height})
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Képgenerálási hiba: {str(e)}")


